VALUES ('6aea9f2f-fedb-5145-9379-bc9bfa42ef03', 'dd75228f-ae95-5860-bde3-db0a25db99bd', 'bcc71e42-3a91-5baf-9842-4816447eeb43', 'a0e97de9-979a-56f6-af50-deacd5e8ff17', 'Organization', 'Supplies organization-specific legal and organizational information for a Party classified as ORGANIZATION. Used for companies, agencies, institutions, nonprofits, and other organizational actors. At most one Organization specialization may describe the party. The specialization is selected by partyType and must not coexist with Person.', 160, 160, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
