INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('11fafcd6-ff40-5459-88cf-5a00a7681d79', 'ad42c24d-836e-52c0-a048-d04e15e9b48e', '976b7ada-e258-5f66-ac43-944d873c7f84', 'a0e97de9-979a-56f6-af50-deacd5e8ff17', 'Parent Organization', 'Immediate parent organizational unit. Supports enterprise hierarchy and organizational scope. Zero or one immediate parent. Determines inherited organizational context where explicitly supported.', 140, 140, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
