VALUES ('b10d0603-6459-532e-b0c7-856bfd96addf', 'dc07b407-e735-5988-b1c7-353237c9f042', 'ea1ec8cb-387c-5333-970d-43a2047fce23', 'a0e97de9-979a-56f6-af50-deacd5e8ff17', 'Status', 'Controls whether the currency is available for new monetary transactions. Used by pricing, order, invoicing, payment, banking, and accounting validation. Retiring a currency must not invalidate historical transactions expressed in that currency. New transactions should use ACTIVE currencies unless an authorized legacy exception applies. Available for normal financial activity. Temporarily unavailable for new normal activity. No longer available for new normal activity while historical financial records remain valid. Required for transaction eligibility. Required — the record cannot be saved while this is empty.', 60, 60, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
