-- --------------------------------------------------------------------------
-- Quality Characteristic (bus_quality_characteristic)
-- --------------------------------------------------------------------------
INSERT INTO sys_window (sys_window_id, name, description, help, window_type, is_sales_transaction, is_default, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('c27bb307-46b5-5209-942c-8d0fffa4af79', 'Quality Characteristic', 'Maintain Quality Characteristic records', 'Create, find and maintain Quality Characteristic records. The list shows every Quality Characteristic you have access to — select a row to open it, or use New to add one. Each row is a single Quality Characteristic, described by 7 fields.

Id and Code are unique: no two Quality Characteristic records may share the same value, and a save that would duplicate one is rejected. Code, Name, Data Type and Status must be filled in before the record can be saved.

Quality Plan Characteristic and Quality Measurement refer back to Quality Characteristic, so what you change here can affect those records.

Every save starts as a Draft. The business rules and workflows attached to Quality Characteristic then run together in a single transaction: if all of them succeed the record becomes Final; if any of them fails, nothing they changed is kept — the record stays Draft and the reason is written onto it so you can fix the cause and retry. A Quality Characteristic with no rules or workflows attached is marked Final immediately.', 'M', FALSE, TRUE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_table (sys_table_id, table_name, name, description, access_level, is_view, is_document, is_high_volume, is_changelog, sys_window_id, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('0cecb574-2f9e-5f79-b0af-ec8a76ce948e', 'bus_quality_characteristic', 'Quality Characteristic', 'Reusable definition of one quality property that can be configured by quality plans and observed through quality measurements. QualityCharacteristic answers what property is being evaluated. It intentionally does not own plan-specific limits because the same property can have different acceptance criteria for different products, suppliers, processes, or inspection plans. Quality master data, inspection design, supplier quality, incoming inspection, process control, laboratory testing, compliance, analytics, and audit. QualityCharacteristic is the reusable semantic definition; QualityPlanCharacteristic configures it for a QualityPlan; QualityPlan selects the governed controls; QualityInspection executes them; QualityMeasurement records observations; Nonconformance may consume failed evidence. Draft → active → retired. Retirement preserves historical references and evidence. Changes to meaning, type, or lifecycle require impact analysis across QualityPlanCharacteristic, QualityPlan, open QualityInspection, QualityMeasurement, Nonconformance, and reporting workflows. Historical completed evidence must retain the definition applicable when it was captured. A WEIGHT characteristic has dataType DECIMAL. One QualityPlanCharacteristic may require 9.8–10.2 kg while another plan may require 9.5–10.5 kg; both use the same reusable QualityCharacteristic.', 'A', FALSE, FALSE, FALSE, TRUE, 'c27bb307-46b5-5209-942c-8d0fffa4af79', 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_tab (sys_tab_id, sys_window_id, sys_table_id, name, help, tab_level, seq_no, is_single_row, has_tree, is_info_tab, is_translation_tab, is_read_only, is_insert_record, is_advanced_tab, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('c04b2e29-10cf-5298-821f-d1dd2b5d5c19', 'c27bb307-46b5-5209-942c-8d0fffa4af79', '0cecb574-2f9e-5f79-b0af-ec8a76ce948e', 'Quality Characteristic', 'Shows one Quality Characteristic at a time. Fields are grouped: General carries the identifying fields and Details carries the rest. 4 fields marked with a red asterisk (*) must have a value before Save will accept the record. Any field showing a ? beside its label has help of its own; click it for the rules that apply there.', 0, 10, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('bc3b6e63-f3c3-5325-9771-05b391f7d2e8', '0cecb574-2f9e-5f79-b0af-ec8a76ce948e', 'id', 'Id', 'Stable identity of the reusable quality characteristic definition. Identifies what property is being measured or observed independently of any one QualityPlan or QualityInspection. Used to reference, reuse, version, search, audit, and integrate a quality characteristic across quality plans and measurements. QualityCharacteristic defines the semantic property; QualityPlanCharacteristic supplies plan-specific acceptance configuration; QualityMeasurement records an observation of it. Required because the characteristic cannot be reliably referenced without a stable identity.', 13, NULL, NULL, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, TRUE, FALSE, 10, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('a060835c-1ed4-5d20-97d6-ea8e7f4ebfc2', '0cecb574-2f9e-5f79-b0af-ec8a76ce948e', 'code', 'Code', 'Business code identifying the quality characteristic. Provides a stable human-readable identifier such as WEIGHT, TEMPERATURE, LENGTH, or APPEARANCE. Used in quality plans, measurements, reports, integrations, and validation rules. The code identifies the characteristic, while QualityPlanCharacteristic determines how that characteristic is controlled in a particular plan. Required for reliable reuse and integration.', 10, 100, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, TRUE, FALSE, FALSE, TRUE, TRUE, 20, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('1d189446-f364-5680-8359-bf18b664b8f5', '0cecb574-2f9e-5f79-b0af-ec8a76ce948e', 'name', 'Name', 'Human-readable name of the quality characteristic. States what property the characteristic represents in language understandable to quality personnel and other users. Used in quality-plan authoring, inspection screens, reports, analytics, and training. Complements code and provides the business-facing meaning of measurements referencing this characteristic. Required so the reusable definition remains understandable.', 10, 300, NULL, FALSE, FALSE, TRUE, TRUE, TRUE, TRUE, FALSE, FALSE, TRUE, TRUE, 30, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('3001305a-9dc3-57c8-bc23-4fae97d7ea99', '0cecb574-2f9e-5f79-b0af-ec8a76ce948e', 'description', 'Description', 'Detailed explanation of the characteristic and its intended interpretation. Clarifies exactly what is observed and prevents different processes from interpreting the same code differently. Quality-plan design, inspection execution, audit, integration, and governance. Explains the semantic property independently of plan-specific limits. Optional when the name and governed definition are already sufficient.', 10, 2000, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 40, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('5838ac50-b2cf-5346-8689-03329be37fec', '0cecb574-2f9e-5f79-b0af-ec8a76ce948e', 'data_type', 'Data Type', 'Data representation expected for observations of this characteristic. Determines whether measurements are numeric or categorical and therefore which evaluation rules are valid. Controls QualityMeasurement value selection, validation, user-interface behavior, and downstream analytics. QualityMeasurement must supply an observation compatible with this data type; QualityPlanCharacteristic supplies applicable criteria. A numeric observation that may contain fractional values. A whole-number observation. A textual or categorical observation represented as text. A true/false observation. An observation selected from a governed set of allowed values. Required because evaluation depends on the characteristic data type.', 1025, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 50, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('ca4f2db7-c9d6-55f9-ba32-8098e28e7653', '0cecb574-2f9e-5f79-b0af-ec8a76ce948e', 'status', 'Status', 'Lifecycle state of the reusable characteristic definition. Controls whether the characteristic may be newly assigned to quality plans and used for new measurements. Governance, authoring, validation, and retirement control. Retiring a characteristic does not erase historical QualityMeasurement evidence or historical plan configurations. Definition is being prepared and is not normally available for new governed use. Definition is approved for use in applicable QualityPlanCharacteristic records. Definition is no longer normally assigned to new configurations but remains available for historical traceability. Required to govern lifecycle behavior.', 1026, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 60, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('9d544c46-bfe4-555e-aef2-07d44a509475', '0cecb574-2f9e-5f79-b0af-ec8a76ce948e', 'evaluation_method', 'Evaluation Method', 'General method or interpretation approach for observing this characteristic. Describes the expected measurement or observation approach when a reusable default is appropriate. Provides guidance for quality-plan authoring and inspection execution. Plan-specific method overrides or requirements belong to QualityPlanCharacteristic when they differ by plan. Optional because some characteristics are self-evident or fully governed by plan-specific configuration.', 10, 500, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 70, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('295ddf0f-3575-5d26-b08d-86807dda023b', 'c04b2e29-10cf-5298-821f-d1dd2b5d5c19', 'bc3b6e63-f3c3-5325-9771-05b391f7d2e8', 'c715c55a-6571-5977-bf6a-8b53827d96cd', 'Id', 'Stable identity of the reusable quality characteristic definition. Identifies what property is being measured or observed independently of any one QualityPlan or QualityInspection. Used to reference, reuse, version, search, audit, and integrate a quality characteristic across quality plans and measurements. QualityCharacteristic defines the semantic property; QualityPlanCharacteristic supplies plan-specific acceptance configuration; QualityMeasurement records an observation of it. Required because the characteristic cannot be reliably referenced without a stable identity. Must be unique: a save is rejected if another Quality Characteristic already uses this value.', 10, 10, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('277edbeb-0648-5490-a199-ed8c129959b4', 'c04b2e29-10cf-5298-821f-d1dd2b5d5c19', 'a060835c-1ed4-5d20-97d6-ea8e7f4ebfc2', 'c715c55a-6571-5977-bf6a-8b53827d96cd', 'Code', 'Business code identifying the quality characteristic. Provides a stable human-readable identifier such as WEIGHT, TEMPERATURE, LENGTH, or APPEARANCE. Used in quality plans, measurements, reports, integrations, and validation rules. The code identifies the characteristic, while QualityPlanCharacteristic determines how that characteristic is controlled in a particular plan. Required for reliable reuse and integration. Required — the record cannot be saved while this is empty. Must be unique: a save is rejected if another Quality Characteristic already uses this value. Up to 100 characters.', 20, 20, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('fb364ad6-04c9-5f4f-ba6a-6b855722f7a8', 'c04b2e29-10cf-5298-821f-d1dd2b5d5c19', '1d189446-f364-5680-8359-bf18b664b8f5', 'c715c55a-6571-5977-bf6a-8b53827d96cd', 'Name', 'Human-readable name of the quality characteristic. States what property the characteristic represents in language understandable to quality personnel and other users. Used in quality-plan authoring, inspection screens, reports, analytics, and training. Complements code and provides the business-facing meaning of measurements referencing this characteristic. Required so the reusable definition remains understandable. Required — the record cannot be saved while this is empty. Up to 300 characters.', 30, 30, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('bc77300b-62d6-5ff7-9d03-b9dccfb60e00', 'c04b2e29-10cf-5298-821f-d1dd2b5d5c19', '3001305a-9dc3-57c8-bc23-4fae97d7ea99', 'a0e97de9-979a-56f6-af50-deacd5e8ff17', 'Description', 'Detailed explanation of the characteristic and its intended interpretation. Clarifies exactly what is observed and prevents different processes from interpreting the same code differently. Quality-plan design, inspection execution, audit, integration, and governance. Explains the semantic property independently of plan-specific limits. Optional when the name and governed definition are already sufficient. Up to 2000 characters.', 40, 40, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('b7d5436e-dc96-52fa-96b9-7ee6633ab654', 'c04b2e29-10cf-5298-821f-d1dd2b5d5c19', '5838ac50-b2cf-5346-8689-03329be37fec', 'a0e97de9-979a-56f6-af50-deacd5e8ff17', 'Data Type', 'Data representation expected for observations of this characteristic. Determines whether measurements are numeric or categorical and therefore which evaluation rules are valid. Controls QualityMeasurement value selection, validation, user-interface behavior, and downstream analytics. QualityMeasurement must supply an observation compatible with this data type; QualityPlanCharacteristic supplies applicable criteria. A numeric observation that may contain fractional values. A whole-number observation. A textual or categorical observation represented as text. A true/false observation. An observation selected from a governed set of allowed values. Required because evaluation depends on the characteristic data type. Required — the record cannot be saved while this is empty.', 50, 50, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('dde76627-556e-53f2-80cc-0dfab05c72c9', 'c04b2e29-10cf-5298-821f-d1dd2b5d5c19', 'ca4f2db7-c9d6-55f9-ba32-8098e28e7653', 'a0e97de9-979a-56f6-af50-deacd5e8ff17', 'Status', 'Lifecycle state of the reusable characteristic definition. Controls whether the characteristic may be newly assigned to quality plans and used for new measurements. Governance, authoring, validation, and retirement control. Retiring a characteristic does not erase historical QualityMeasurement evidence or historical plan configurations. Definition is being prepared and is not normally available for new governed use. Definition is approved for use in applicable QualityPlanCharacteristic records. Definition is no longer normally assigned to new configurations but remains available for historical traceability. Required to govern lifecycle behavior. Required — the record cannot be saved while this is empty.', 60, 60, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('dab1a8a7-848f-58f7-80ef-97d49ce68b65', 'c04b2e29-10cf-5298-821f-d1dd2b5d5c19', '9d544c46-bfe4-555e-aef2-07d44a509475', 'a0e97de9-979a-56f6-af50-deacd5e8ff17', 'Evaluation Method', 'General method or interpretation approach for observing this characteristic. Describes the expected measurement or observation approach when a reusable default is appropriate. Provides guidance for quality-plan authoring and inspection execution. Plan-specific method overrides or requirements belong to QualityPlanCharacteristic when they differ by plan. Optional because some characteristics are self-evident or fully governed by plan-specific configuration. Up to 500 characters.', 70, 70, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_access (sys_access_id, sys_role_id, sys_table_id, sys_window_id, access_type_table, is_read_only, is_exclude, entity_type, is_active, created_by, updated_by, created_at, updated_at)
