INSERT INTO sys_access (sys_access_id, sys_role_id, sys_table_id, sys_window_id, access_type_table, is_read_only, is_exclude, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('810a3330-5360-50d1-a020-5c429337bb5e', (SELECT sys_role_id FROM sys_role WHERE name = 'User'), '0cecb574-2f9e-5f79-b0af-ec8a76ce948e', 'c27bb307-46b5-5209-942c-8d0fffa4af79', 'R', TRUE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
