INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('92fb685b-cb11-5070-ba2a-2d3e24e04143', '97f01bc2-b81d-5cc5-82b1-d2548ac3c496', '73e81532-648b-5575-9224-dc6dd3f080fe', 'c715c55a-6571-5977-bf6a-8b53827d96cd', 'Id', 'Stable identity of one characteristic configuration within a QualityPlan. Identifies the specific plan-level requirement that governs how one QualityCharacteristic is inspected. Traceability, configuration, inspection execution, audit, and integration. Links one QualityPlan to one reusable QualityCharacteristic and its plan-specific criteria. Required because plan-level requirements need an unambiguous identity. Must be unique: a save is rejected if another Quality Plan Characteristic already uses this value.', 10, 10, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('331fc244-6884-5324-822f-e5868c6a4397', '97f01bc2-b81d-5cc5-82b1-d2548ac3c496', '208cb724-85bb-5d8a-ab55-214642c9dd47', 'c715c55a-6571-5977-bf6a-8b53827d96cd', 'Sequence Number', 'Execution or presentation order of this quality characteristic within the plan. Determines where the characteristic appears in inspection instructions and can support ordered sampling or testing. Inspection forms, operator guidance, reports, and workflow orchestration. Sequence is scoped to the QualityPlan and does not change the reusable characteristic''s identity. Required where plan execution requires deterministic ordering. Required — the record cannot be saved while this is empty.', 20, 20, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('6ea1d45a-dc60-5c84-a8d3-65ab8f70e820', '97f01bc2-b81d-5cc5-82b1-d2548ac3c496', 'ac3cbfa1-7d35-5be5-8007-1ffbdaa72ee8', 'c715c55a-6571-5977-bf6a-8b53827d96cd', 'Required', 'Indicates whether evidence for this characteristic is mandatory for the governing plan. Determines whether the absence of a measurement can prevent inspection completion. Inspection validation, completion gating, audit, and exception handling. QualityInspection uses this setting when determining whether all required measurements have been evaluated. Required because optional and mandatory characteristics have different workflow consequences. Required — the record cannot be saved while this is empty.', 30, 30, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('7a8a49fd-a05f-55da-b100-c068df514f8c', '97f01bc2-b81d-5cc5-82b1-d2548ac3c496', 'a30a12e8-4a82-572d-b8c7-1eb5abd0f229', 'a0e97de9-979a-56f6-af50-deacd5e8ff17', 'Lower Limit', 'Plan-specific lower acceptance boundary for a numeric characteristic. Defines the minimum acceptable value under this particular QualityPlan. Automated evaluation and inspection review. Applies only to the linked QualityCharacteristic in this plan and must use a compatible unit. Optional when the criterion has no lower numeric boundary.', 40, 40, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('cb8ea3db-443d-50c3-8a51-eb7335a25b9f', '97f01bc2-b81d-5cc5-82b1-d2548ac3c496', '31c9ea81-7327-5f11-ba28-1d456eb276b9', 'a0e97de9-979a-56f6-af50-deacd5e8ff17', 'Upper Limit', 'Plan-specific upper acceptance boundary for a numeric characteristic. Defines the maximum acceptable value under this particular QualityPlan. Automated evaluation and inspection review. Applies only to the linked QualityCharacteristic in this plan and must use a compatible unit. Optional when the criterion has no upper numeric boundary.', 50, 50, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('bbf15f96-eb01-5277-b588-7fffdbdabeff', '97f01bc2-b81d-5cc5-82b1-d2548ac3c496', '3cd8199b-7a43-57d1-adba-31d2f8ab256c', 'a0e97de9-979a-56f6-af50-deacd5e8ff17', 'Target Value', 'Preferred numeric target for the characteristic under this plan. Represents the desired value rather than the minimum or maximum acceptance boundary. Process optimization, inspection guidance, analytics, and trend analysis. Must be compatible with the characteristic data type and acceptance limits. Optional where only pass/fail boundaries are relevant.', 60, 60, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('7098a11c-6300-5256-abc5-6c5545fe35c7', '97f01bc2-b81d-5cc5-82b1-d2548ac3c496', '46c37218-95ae-54ea-9329-f1751f5b7fcb', 'a0e97de9-979a-56f6-af50-deacd5e8ff17', 'Unit Of Measure', 'Unit used for numeric limits and target values in this plan configuration. Gives dimensional meaning to the configured numeric criteria. Measurement evaluation, conversion, reporting, and audit. Must be dimensionally compatible with the QualityCharacteristic and QualityMeasurement unit. Optional for unitless or non-numeric characteristics.', 70, 70, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('19e20bf3-4286-5fda-85a8-6fbd083e72e3', '97f01bc2-b81d-5cc5-82b1-d2548ac3c496', 'eef4aac0-4260-5905-b679-20d5d4111cab', 'a0e97de9-979a-56f6-af50-deacd5e8ff17', 'Method', 'Plan-specific procedure or method required to evaluate the characteristic. Defines how the characteristic must be observed when this plan is executed. Inspection instructions, reproducibility, compliance, and audit. May refine or override the reusable QualityCharacteristic evaluationMethod. Optional when the reusable characteristic method is sufficient. Up to 500 characters.', 80, 80, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('41b651e8-3483-563f-a221-75e178640017', '97f01bc2-b81d-5cc5-82b1-d2548ac3c496', 'ebaa20ee-ba6b-52d4-b452-abfcd64ab0dc', 'a0e97de9-979a-56f6-af50-deacd5e8ff17', 'Sampling Required', 'Indicates whether this characteristic participates in explicit sampling controls under the plan. Distinguishes characteristics that require sampled observations from those evaluated on every applicable inspection item. Sampling workflow design and inspection execution. When true, the samplingPlan relationship identifies the governed selection policy used for this characteristic. Required to make sampling participation explicit. Required — the record cannot be saved while this is empty.', 90, 90, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('fa545dee-1b94-5cb1-9823-1aae23c0434a', '97f01bc2-b81d-5cc5-82b1-d2548ac3c496', '8e2cfe11-21f8-52f3-98fa-d8590a85ff28', 'a0e97de9-979a-56f6-af50-deacd5e8ff17', 'Quality Characteristic', 'Reusable quality property being controlled by this plan configuration. Identifies what is observed while this entity supplies the context-specific acceptance rules. Reuse, semantic interpretation, measurement linkage, and governance. Every configuration references exactly one reusable QualityCharacteristic. Separating reusable meaning from plan-specific criteria prevents conflicting definitions when the same property is used by multiple plans. Required — the record cannot be saved while this is empty.', 100, 100, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('17c83d5e-04fc-5d4b-8e37-896563bd392c', '97f01bc2-b81d-5cc5-82b1-d2548ac3c496', 'f7783271-51ed-52f2-b509-43da6648992d', 'a0e97de9-979a-56f6-af50-deacd5e8ff17', 'Quality Plan', 'QualityPlan in which this characteristic requirement is configured. Provides the governing inspection context for the requirement. Plan authoring, inspection execution, traceability, and lifecycle control. Every configuration belongs to exactly one QualityPlan. The plan determines when and why the configured characteristic is evaluated. Required — the record cannot be saved while this is empty.', 110, 110, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('c59f4b6b-186b-5a52-b672-3a827992ad0b', '97f01bc2-b81d-5cc5-82b1-d2548ac3c496', 'bca0e9cd-fae4-590d-a346-ea94d88b4069', 'a0e97de9-979a-56f6-af50-deacd5e8ff17', 'Test Method', 'Governed reusable procedure required to evaluate this characteristic in the plan. Replaces ambiguous free-text method interpretation with an authoritative method definition while allowing method text to remain a historical or integration snapshot. Inspection execution, laboratory testing, reproducibility, training, compliance, and audit. A plan characteristic uses zero or one governed TestMethod when a reusable controlled method applies. TestMethod defines how evidence is produced; this entity defines what criteria that evidence must satisfy.', 120, 120, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('9e0cd882-3122-50f3-a9a6-b581c64140ba', '97f01bc2-b81d-5cc5-82b1-d2548ac3c496', 'a560e8d8-5375-551b-81c4-e008cded06a1', 'a0e97de9-979a-56f6-af50-deacd5e8ff17', 'Sampling Plan', 'SamplingPlan governing how observations of this characteristic are selected when samplingRequired is true. Connects a plan-specific characteristic requirement to the deterministic sample-selection policy used during inspection. Sample-size calculation, inspection execution, completion gating, audit, and reproducibility. A characteristic requirement uses zero or one sampling plan; zero is appropriate when every applicable unit is evaluated or sampling is governed elsewhere. SamplingPlan defines selection policy; SamplingRule supplies conditional sample quantities and acceptance thresholds.', 130, 130, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
