-- --------------------------------------------------------------------------
-- Test Method (bus_test_method)
-- --------------------------------------------------------------------------
INSERT INTO sys_window (sys_window_id, name, description, help, window_type, is_sales_transaction, is_default, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('c2fc5cd3-a2b9-5fe6-911c-31920e72f516', 'Test Method', 'Maintain Test Method records', 'Create, find and maintain Test Method records. The list shows every Test Method you have access to — select a row to open it, or use New to add one. Each row is a single Test Method, described by 5 fields.

Id and Code are unique: no two Test Method records may share the same value, and a save that would duplicate one is rejected. Code, Name and Status must be filled in before the record can be saved.

Quality Plan Characteristic and Quality Measurement refer back to Test Method, so what you change here can affect those records.

Every save starts as a Draft. The business rules and workflows attached to Test Method then run together in a single transaction: if all of them succeed the record becomes Final; if any of them fails, nothing they changed is kept — the record stays Draft and the reason is written onto it so you can fix the cause and retry. A Test Method with no rules or workflows attached is marked Final immediately.', 'M', FALSE, TRUE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_table (sys_table_id, table_name, name, description, access_level, is_view, is_document, is_high_volume, is_changelog, sys_window_id, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('d07e8a22-030a-534a-abcc-cc88afb4f3a9', 'bus_test_method', 'Test Method', 'Reusable governed procedure for producing quality evidence. TestMethod separates how an observation is produced from what QualityCharacteristic is observed and what QualityPlanCharacteristic criteria apply. Quality planning, laboratory testing, incoming inspection, compliance, training, audit, and analytics. QualityPlanCharacteristic selects the method; QualityMeasurement records evidence produced under it. Draft → active → suspended/retired under controlled change. Method lifecycle or semantic changes revalidate affected open configurations and inspections while completed evidence remains historically stable.', 'A', FALSE, FALSE, FALSE, TRUE, 'c2fc5cd3-a2b9-5fe6-911c-31920e72f516', 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
