-- --------------------------------------------------------------------------
INSERT INTO sys_window (sys_window_id, name, description, help, window_type, is_sales_transaction, is_default, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('03c42084-7445-54b8-bc7b-0bdda9eab1a3', 'Sampling Plan', 'Maintain Sampling Plan records', 'Create, find and maintain Sampling Plan records. The list shows every Sampling Plan you have access to — select a row to open it, or use New to add one. Each row is a single Sampling Plan, described by 5 fields.

Id and Code are unique: no two Sampling Plan records may share the same value, and a save that would duplicate one is rejected. Code, Name, Method and Status must be filled in before the record can be saved.

Quality Plan Characteristic, Sampling Rule and Inspection Sample refer back to Sampling Plan, so what you change here can affect those records.

Every save starts as a Draft. The business rules and workflows attached to Sampling Plan then run together in a single transaction: if all of them succeed the record becomes Final; if any of them fails, nothing they changed is kept — the record stays Draft and the reason is written onto it so you can fix the cause and retry. A Sampling Plan with no rules or workflows attached is marked Final immediately.', 'M', FALSE, TRUE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_table (sys_table_id, table_name, name, description, access_level, is_view, is_document, is_high_volume, is_changelog, sys_window_id, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('f1d26c5b-397a-5b49-ab5b-090e718d2b71', 'bus_sampling_plan', 'Sampling Plan', 'Reusable governed definition for selecting inspection samples. SamplingPlan separates the statistical or operational selection policy from the QualityInspection transaction that executes it. Incoming inspection, supplier quality, process control, laboratory testing, compliance, acceptance sampling, and audit. QualityPlan determines the broader quality controls; SamplingPlan defines how populations are sampled; SamplingRule defines conditional sample quantities and acceptance criteria; inspection execution records the actual selection. Draft → active → suspended/retired. Historical executions retain their governing configuration. Changes propagate to QualityPlans, open inspections, sample-selection transactions, measurement coverage, and inspection completion gating. Completed sample evidence is never silently reinterpreted. A receiving quality plan uses an acceptance-sampling SamplingPlan with different sample sizes for small, medium, and large lot-size ranges.', 'A', FALSE, FALSE, FALSE, TRUE, '03c42084-7445-54b8-bc7b-0bdda9eab1a3', 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
