VALUES ('1dcc5950-e516-5ae3-a4f8-13f0737ea146', '03c42084-7445-54b8-bc7b-0bdda9eab1a3', 'f1d26c5b-397a-5b49-ab5b-090e718d2b71', 'Sampling Plan', 'Shows one Sampling Plan at a time. Fields are grouped: General carries the identifying fields and Details carries the rest. 4 fields marked with a red asterisk (*) must have a value before Save will accept the record. Any field showing a ? beside its label has help of its own; click it for the rules that apply there.', 0, 10, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
