INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('7c47d3a6-75de-5f94-8caa-4bb0b7cb0024', '1dcc5950-e516-5ae3-a4f8-13f0737ea146', 'a4525daa-26a2-5955-ab65-a759fd88f0ba', 'c715c55a-6571-5977-bf6a-8b53827d96cd', 'Code', 'Business code identifying the sampling plan. Provides a stable operational reference for a governed sampling definition. Plan selection, inspection authoring, reports, and integrations. Identifies the sampling definition rather than an individual sample or inspection. Required. Required — the record cannot be saved while this is empty. Must be unique: a save is rejected if another Sampling Plan already uses this value. Up to 100 characters.', 20, 20, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
