VALUES ('32f9cac7-1728-5556-8d6c-834d5537b1aa', '5f027594-f39b-5c69-9285-779309d8b2c7', 'dcc2181b-fafb-5e2b-97cb-15ababf06bdd', 'a0e97de9-979a-56f6-af50-deacd5e8ff17', 'Population Max', 'Maximum population quantity for which this rule applies. Defines the upper boundary of the eligible lot or population range. Rule selection and deterministic sampling execution. Interpreted with populationMin and sampleSize. Optional when the rule has no upper population boundary.', 40, 40, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('57d66ca6-8b84-5f01-ac9d-72688f85dc94', '5f027594-f39b-5c69-9285-779309d8b2c7', '9a0b6fa8-ecef-5b45-bfcf-f9ff5862deb5', 'a0e97de9-979a-56f6-af50-deacd5e8ff17', 'Sample Size', 'Number of units or observations to select when this rule applies. Defines the required sample quantity before the inspection can satisfy the sampling requirement. Sample selection, inspection execution, and completion gating. Must not exceed the eligible population except where the governing method explicitly permits census behavior. Required. Required — the record cannot be saved while this is empty.', 50, 50, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('3d3ea707-9c14-559e-85fa-221bbf698532', '5f027594-f39b-5c69-9285-779309d8b2c7', 'db887385-50e4-532c-93ea-cd20da2674c1', 'a0e97de9-979a-56f6-af50-deacd5e8ff17', 'Acceptance Number', 'Maximum number of failing sampled units permitted for acceptance under this rule. Defines the failure threshold for acceptance-sampling plans. Automated sample evaluation and inspection decision support. Used with rejectionNumber and sample results when method is acceptance sampling. Optional when the plan uses another acceptance mechanism.', 60, 60, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('02862c74-2744-5614-a198-6a26ce997859', '5f027594-f39b-5c69-9285-779309d8b2c7', '0973269a-4481-5926-bb12-1fcad745628e', 'a0e97de9-979a-56f6-af50-deacd5e8ff17', 'Rejection Number', 'Number of failing sampled units at which the sampled population is rejected. Defines the rejection threshold for acceptance-sampling plans. Automated evaluation and inspection decision support. Must be greater than acceptanceNumber when both are configured. Optional when the plan uses another acceptance mechanism.', 70, 70, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('d8dda050-4921-517a-82c4-07788f5cff44', '5f027594-f39b-5c69-9285-779309d8b2c7', 'e4b6c299-5d1c-5a39-b794-8e8e8e5c9e48', 'a0e97de9-979a-56f6-af50-deacd5e8ff17', 'Status', 'Lifecycle state of the sampling rule. Controls whether the rule can be selected for new sample executions. Governance, authoring, and inspection execution. Retired rules remain available for historical sample traceability. Rule is being prepared and is not normally selectable. Rule is approved for sampling execution. Rule is no longer selected for new sampling but remains historical evidence. Required. Required — the record cannot be saved while this is empty.', 80, 80, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('d04991d7-ce78-565f-8a2a-951d9287b35d', '5f027594-f39b-5c69-9285-779309d8b2c7', '9179fc0a-86c5-5bb9-8772-cfbecf2c59c7', 'a0e97de9-979a-56f6-af50-deacd5e8ff17', 'Sampling Plan', 'SamplingPlan that owns this conditional sampling rule. Provides the overall sampling method and governance context. Rule selection, execution, traceability, and audit. Every rule belongs to exactly one SamplingPlan. The plan supplies the method; the rule supplies conditional quantity and acceptance parameters. Required — the record cannot be saved while this is empty.', 90, 90, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('5f832dad-5274-54d6-af4a-9d1cca4b3cd9', '5f027594-f39b-5c69-9285-779309d8b2c7', 'b7ee652c-a89e-5e62-aedf-8ef224519fbe', 'a0e97de9-979a-56f6-af50-deacd5e8ff17', 'Quality Plan', 'QualityPlan in which this rule is specifically used when a direct plan association is needed. Provides explicit traceability from a sampling rule to the quality plan it supports. Plan impact analysis, reporting, governance, and integration. A rule may be reusable or directly associated with one QualityPlan. When populated, the associated QualityPlan must agree with the SamplingPlan assignment.', 100, 100, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
