VALUES ('464cd57b-2e5b-5cb4-bf45-4e588aa0e09c', '0a38c1e2-db68-5edc-bd2f-259decf14a24', 'f9d2cc67-a726-5c2b-abd2-1064e53c7681', 'a0e97de9-979a-56f6-af50-deacd5e8ff17', 'Status', 'Lifecycle state of inspection. Indicates whether inspection is pending, executing, completed with a result, or cancelled. Controls release and disposition workflows. Inspection status is independent of sample status, receipt/return status, and inventory state. PASSED/FAILED/CONDITIONAL controls eligible disposition. Required. Required — the record cannot be saved while this is empty.', 40, 40, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
