INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('3efbb870-a626-5a74-a42a-737be1531d36', '0a38c1e2-db68-5edc-bd2f-259decf14a24', '4adb0adf-6623-5e0d-9f02-9ccf473b1e57', 'a0e97de9-979a-56f6-af50-deacd5e8ff17', 'Inspector', 'Party performing or accountable for inspection. Identifies inspector or quality authority. Accountability, audit and compliance. Provides execution responsibility.', 90, 90, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
