VALUES ('237cc95b-c128-588b-8a0a-3720ed406f22', 'b3dfbcaa-d835-569f-895d-8f1b7c6a8bfe', '17568d3c-35af-508b-b6b3-04a07c33b403', 'a0e97de9-979a-56f6-af50-deacd5e8ff17', 'Unit Of Measure', 'Unit in which the sample quantity is expressed. Gives semantic meaning to the selected sample quantity. Reconciliation, reporting, conversion, and audit. Must be compatible with the source population and governing sampling configuration. Required. Required — the record cannot be saved while this is empty.', 50, 50, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('bfd1d6d0-d381-5bc2-86b4-75287010dbb3', 'b3dfbcaa-d835-569f-895d-8f1b7c6a8bfe', '1e76c913-099f-5902-bb09-2c37b2ce5ac6', 'a0e97de9-979a-56f6-af50-deacd5e8ff17', 'Status', 'Lifecycle state of the selected sample. Shows whether the sample is awaiting testing, being tested, has completed testing, or has been otherwise dispositioned. Sample handling, measurement gating, chain of custody, and audit. Sample status is distinct from overall QualityInspection status and does not independently determine product disposition. Sample has been selected and is awaiting testing or handling. Sample is actively undergoing governed testing. Required testing for the sample has completed. Sample itself was rejected or invalidated for the governed purpose. Sample has been physically disposed of under an authorized process. Sample selection was cancelled under controlled workflow. Required. Required — the record cannot be saved while this is empty.', 60, 60, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('42489feb-1d7b-52f0-ab13-6b01b2017754', 'b3dfbcaa-d835-569f-895d-8f1b7c6a8bfe', '4807fc6a-a1be-5608-9162-999cf9b5b714', 'a0e97de9-979a-56f6-af50-deacd5e8ff17', 'Selection Basis', 'Evidence or description of how this particular sample was selected. Preserves the operational selection basis needed to reproduce or audit the sampling event. Compliance, audit, supplier disputes, and statistical review. Complements the authoritative SamplingRule and does not replace it. Optional when selection is fully reproducible from the governed rule and execution metadata. Up to 1000 characters.', 70, 70, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('6db9c7fe-2adc-567a-a4c6-aa4498c4230c', 'b3dfbcaa-d835-569f-895d-8f1b7c6a8bfe', '3bc396d2-6ecf-5b81-aa9f-d38a1ed2d73e', 'a0e97de9-979a-56f6-af50-deacd5e8ff17', 'Quality Inspection', 'QualityInspection for which this sample was selected. Provides the execution context and population being inspected. Sample traceability, inspection completion, measurement linkage, and audit. Every InspectionSample belongs to exactly one QualityInspection. Inspection status and result remain independent; the sample supplies evidence to the inspection. Required — the record cannot be saved while this is empty.', 80, 80, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('8fba62cf-f042-584b-a927-38127ed0684e', 'b3dfbcaa-d835-569f-895d-8f1b7c6a8bfe', 'f9f998bf-cc38-5bbd-90bd-fcd226fbeec3', 'a0e97de9-979a-56f6-af50-deacd5e8ff17', 'Sampling Plan', 'SamplingPlan governing the sample-selection event. Preserves the reusable sampling policy applied at execution time. Audit, reproducibility, analytics, and change-impact analysis. A sample may reference zero or one sampling plan when sampling is not governed by an explicit reusable plan. When populated, the plan must agree with the governing SamplingRule.', 90, 90, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('8d7b0c50-27ee-55c9-9e7c-61105be3414c', 'b3dfbcaa-d835-569f-895d-8f1b7c6a8bfe', 'a254a1a9-fda1-591a-aa76-f0c5daf065ec', 'a0e97de9-979a-56f6-af50-deacd5e8ff17', 'Sampling Rule', 'SamplingRule used to determine this sample selection. Identifies the exact conditional rule that determined sample quantity and acceptance logic. Audit, reproducibility, sample reconciliation, and inspection completion. A sample may have zero or one rule only when an explicit rule is not applicable. When populated, the rule and SamplingPlan must be mutually consistent.', 100, 100, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
