INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('77ee61e3-6f2e-5fb3-82e0-9ff8edd8dc52', '7129094f-6a92-567d-82ca-cfd9be683e5d', 'cc18fce5-d6ad-5cdc-8bfb-68bfee2370eb', 'c715c55a-6571-5977-bf6a-8b53827d96cd', 'Id', 'Stable identity of one quality measurement. Identifies one observation independently of its inspection and characteristic. Traceability, audit, analytics and integrations. Distinct from QualityInspection and the measured Product. Stable reference from capture through review. Required. Must be unique: a save is rejected if another Quality Measurement already uses this value.', 10, 10, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('cec20be9-1220-52c7-ab66-f4c00aba4524', '7129094f-6a92-567d-82ca-cfd9be683e5d', 'da451262-5afb-53c8-8595-c0fec6800638', 'c715c55a-6571-5977-bf6a-8b53827d96cd', 'Measurement Number', 'Human-facing measurement reference. Provides an operational identifier for one observation. Inspection review, audit and integration. Distinct from the parent inspection number. Supports individual observation traceability. Required. Required — the record cannot be saved while this is empty. Must be unique: a save is rejected if another Quality Measurement already uses this value. Up to 100 characters.', 20, 20, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('00aacab3-b128-54e9-9f15-eee62d3bedf3', '7129094f-6a92-567d-82ca-cfd9be683e5d', '342ff7ba-453b-58e8-903a-4d1853bc987b', 'c715c55a-6571-5977-bf6a-8b53827d96cd', 'Characteristic Code', 'Snapshot of the quality characteristic business code evaluated by this observation. Preserves the human-readable characteristic identifier applicable when evidence was captured. Audit, reporting, exports and legacy integration. Must correspond to the linked QualityCharacteristic through QualityPlanCharacteristic and must not be treated as the authoritative configuration key. Provides readable historical context while the relationship graph supplies authoritative semantics. Required for operational readability and historical evidence. Required — the record cannot be saved while this is empty. Up to 100 characters.', 30, 30, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('c6cb3dd6-b7d3-51bf-8649-6a376cbce0b6', '7129094f-6a92-567d-82ca-cfd9be683e5d', '17f4f8e9-b3f1-52f2-94ab-86a65245729a', 'a0e97de9-979a-56f6-af50-deacd5e8ff17', 'Measured Value', 'Numeric value observed during inspection. Records the factual quantitative observation before evaluation. Acceptance evaluation, trend analysis and audit. Requires a compatible unit for dimensional characteristics. Supplies evidence used against configured acceptance criteria. Optional for categorical characteristics.', 40, 40, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('174d0cc2-e3a4-5ab0-9a08-43f2be6b8a98', '7129094f-6a92-567d-82ca-cfd9be683e5d', '4a5ceb1a-3c40-563b-b5d8-ea3d37ea5902', 'a0e97de9-979a-56f6-af50-deacd5e8ff17', 'Measured Text', 'Categorical or textual observation. Records observations such as color, grade, appearance or classification. Quality evaluation where numeric measurement is inappropriate. Used instead of measuredValue for categorical characteristics. Supplies structured qualitative evidence. Optional for numeric characteristics. Up to 1000 characters.', 50, 50, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('89b4b529-779b-52c9-9988-91a7d45c7cc7', '7129094f-6a92-567d-82ca-cfd9be683e5d', '92006a1c-7e99-5ecc-8129-fb0ea7a6ae15', 'a0e97de9-979a-56f6-af50-deacd5e8ff17', 'Unit Of Measure', 'Unit in which a numeric measurement is expressed. Defines the dimensional interpretation of measuredValue. Comparison, conversion, reporting and audit. Must be compatible with the linked QualityPlanCharacteristic and QualityCharacteristic. Makes numeric observations semantically comparable. Optional for unitless or categorical characteristics.', 60, 60, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('db1bb6fd-415e-524a-bf0b-bbff18119bda', '7129094f-6a92-567d-82ca-cfd9be683e5d', '748666c4-eef7-58d1-861b-ff8f816b8faf', 'a0e97de9-979a-56f6-af50-deacd5e8ff17', 'Lower Limit', 'Snapshot of the lower acceptance boundary applicable when the measurement was evaluated. Preserves the criterion used to evaluate the historical observation. Audit, reproducibility and review. Normally copied from QualityPlanCharacteristic rather than independently defining a new requirement. Makes the evaluation auditable even if the plan later changes. Optional when no lower boundary applies.', 70, 70, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
