-- --------------------------------------------------------------------------
-- Corrective Action (bus_corrective_action)
-- --------------------------------------------------------------------------
INSERT INTO sys_window (sys_window_id, name, description, help, window_type, is_sales_transaction, is_default, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('0b2fd043-d984-5a50-b0cf-ce391062dd94', 'Corrective Action', 'Maintain Corrective Action records', 'Create, find and maintain Corrective Action records. The list shows every Corrective Action you have access to — select a row to open it, or use New to add one. Each row is a single Corrective Action, described by 9 fields.

Id and Action Number are unique: no two Corrective Action records may share the same value, and a save that would duplicate one is rejected. Action Number, Action Type, Description and Status must be filled in before the record can be saved.

Every Corrective Action points at Nonconformance. Choose the linked record from the lookup on those fields rather than typing an identifier. Corrective Action Verification refers back to Corrective Action, so what you change here can affect that record.

Every save starts as a Draft. The business rules and workflows attached to Corrective Action then run together in a single transaction: if all of them succeed the record becomes Final; if any of them fails, nothing they changed is kept — the record stays Draft and the reason is written onto it so you can fix the cause and retry. A Corrective Action with no rules or workflows attached is marked Final immediately.', 'M', FALSE, TRUE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_table (sys_table_id, table_name, name, description, access_level, is_view, is_document, is_high_volume, is_changelog, sys_window_id, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('fc395ad0-293c-5b8c-a24f-4c05bdb3580f', 'bus_corrective_action', 'Corrective Action', 'Represents a controlled quality action from assignment through implementation and independent effectiveness verification. Nonconformance records the problem; CorrectiveAction records what is done to contain, correct or prevent it; CorrectiveActionVerification records whether the action worked. CAPA, supplier quality, compliance, audit, recurrence prevention and quality improvement. The action connects Nonconformance with responsible Party and one or more CorrectiveActionVerification records. Physical and financial consequences remain represented by their own transactions. Open → assigned → in progress → verification → completed, with cancellation and reopening paths. Nonconformance → action definition → assignment → implementation → verification → effective completion → Nonconformance closure when all required evidence is satisfied. Ineffective verification returns the action to controlled follow-up. Changes to the originating Nonconformance or quality evidence affecting the action trigger revalidation of scope and verification criteria. Verification results may reopen or create additional action work; historical records remain immutable. A supplier defect causes a corrective action to change packaging controls. The action is implemented, a verification evaluates subsequent lots, and only an EFFECTIVE verification permits completion when policy requires effectiveness evidence.', 'A', FALSE, FALSE, FALSE, TRUE, '0b2fd043-d984-5a50-b0cf-ce391062dd94', 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_tab (sys_tab_id, sys_window_id, sys_table_id, name, help, tab_level, seq_no, is_single_row, has_tree, is_info_tab, is_translation_tab, is_read_only, is_insert_record, is_advanced_tab, entity_type, is_active, created_by, updated_by, created_at, updated_at)
