VALUES ('066a96a8-5e4e-5103-81c7-8caa481dd403', 'fc395ad0-293c-5b8c-a24f-4c05bdb3580f', 'id', 'Id', 'Immutable identity of the corrective action. Identifies one controlled quality action independently of its issue, owner, implementation evidence or verification. CAPA, quality audit, supplier improvement and compliance. Distinct from Nonconformance and CorrectiveActionVerification identities. Stable reference through assignment, execution, verification and closure. Required.', 13, NULL, NULL, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, TRUE, FALSE, 10, 'U', TRUE, 'system', 'system', NOW(), NOW())
