-- --------------------------------------------------------------------------
-- Corrective Action Verification (bus_corrective_action_verification)
-- --------------------------------------------------------------------------
INSERT INTO sys_window (sys_window_id, name, description, help, window_type, is_sales_transaction, is_default, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('0ad9e0b9-c4a3-565f-be34-6a1e9866adfe', 'Corrective Action Verification', 'Maintain Corrective Action Verification records', 'Create, find and maintain Corrective Action Verification records. The list shows every Corrective Action Verification you have access to — select a row to open it, or use New to add one. Each row is a single Corrective Action Verification, described by 9 fields.

Id and Verification Number are unique: no two Corrective Action Verification records may share the same value, and a save that would duplicate one is rejected. Verification Number, Verification Date, Result, Status, Findings, Verified By and Corrective Action must be filled in before the record can be saved.

Every Corrective Action Verification points at Nonconformance and Corrective Action. Choose the linked record from the lookup on those fields rather than typing an identifier.

Every save starts as a Draft. The business rules and workflows attached to Corrective Action Verification then run together in a single transaction: if all of them succeed the record becomes Final; if any of them fails, nothing they changed is kept — the record stays Draft and the reason is written onto it so you can fix the cause and retry. A Corrective Action Verification with no rules or workflows attached is marked Final immediately.', 'M', FALSE, TRUE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_table (sys_table_id, table_name, name, description, access_level, is_view, is_document, is_high_volume, is_changelog, sys_window_id, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('c88e3563-d132-5b22-9599-8f6c6b91f6c9', 'bus_corrective_action_verification', 'Corrective Action Verification', 'Provides independent auditable evidence that a corrective or preventive action achieved its intended result. CorrectiveAction records what was done; CorrectiveActionVerification records whether it worked; Nonconformance records the original quality problem. CAPA supplier quality compliance audit recurrence prevention and issue closure. Verification closes the evidence loop between Nonconformance and CorrectiveAction without conflating implementation with effectiveness. Nonconformance → CorrectiveAction → implementation → effectiveness verification → effective closure or ineffective/reopened action → Nonconformance closure when all required evidence is satisfied. Open → in progress → completed, with reopened or cancelled paths. Ineffective verification reopens or creates additional CorrectiveAction work according to policy; it must not silently close the underlying Nonconformance. A supplier defect causes a corrective action requiring a packaging-process change. After implementation, verification evaluates subsequent lots, records EFFECTIVE, and provides evidence needed to complete the action and eventually close the nonconformance.', 'A', FALSE, FALSE, FALSE, TRUE, '0ad9e0b9-c4a3-565f-be34-6a1e9866adfe', 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
