INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('eccae2ea-e72b-56e3-8522-52e6310213e7', '69464589-f31c-5dd1-a3ca-629f6c1844d4', 'b623dc52-509a-5265-94b0-74a8292da97e', 'c715c55a-6571-5977-bf6a-8b53827d96cd', 'Id', 'Stable identity of the return disposition decision. Identifies one controlled disposition event independently of the return, inspection and resulting inventory or financial effects. Used for reverse logistics, inventory, quality, audit and reconciliation. CustomerReturn or SupplierReturn supplies the returned-material context; QualityInspection may supply quality evidence; InventoryMovement records physical consequence. Carries the disposition decision into execution and completion. Required. Must be unique: a save is rejected if another Return Disposition already uses this value.', 10, 10, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('40fac29a-4e05-5d1c-bbd1-10a80989845f', '69464589-f31c-5dd1-a3ca-629f6c1844d4', 'a8cbf9e2-d592-5092-aee1-b76244c49c5e', 'c715c55a-6571-5977-bf6a-8b53827d96cd', 'Disposition Code', 'Controlled operational outcome selected for returned material. Defines what should happen to the returned quantity. Drives warehouse execution, quality containment and eligibility for inventory availability. The code is a decision, not the inventory transaction itself and not a CreditNote or SupplierCreditNote. Determines which downstream physical workflow is permitted. Required. Required — the record cannot be saved while this is empty.', 20, 20, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
