VALUES ('f91f301b-4089-50b4-8c71-67bc68d02558', '69464589-f31c-5dd1-a3ca-629f6c1844d4', '3e75e12d-505a-5f1a-ba55-b032880956b9', 'c715c55a-6571-5977-bf6a-8b53827d96cd', 'Disposition Date', 'Timestamp when the disposition became effective. Establishes chronology for the physical return decision. Supports audit, warehouse processing, SLA measurement and reconciliation. Distinct from returnDate, receiptDate and financial adjustment dates. Anchors execution of the disposition. Required. Required — the record cannot be saved while this is empty.', 30, 30, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
