-- --------------------------------------------------------------------------
-- Certificate Of Analysis (bus_certificate_of_analysis)
-- --------------------------------------------------------------------------
INSERT INTO sys_window (sys_window_id, name, description, help, window_type, is_sales_transaction, is_default, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('e0ebc497-91da-5163-9c3b-f937c5a035f9', 'Certificate Of Analysis', 'Maintain Certificate Of Analysis records', 'Create, find and maintain Certificate Of Analysis records. The list shows every Certificate Of Analysis you have access to — select a row to open it, or use New to add one. Each row is a single Certificate Of Analysis, described by 4 fields.

Id and Certificate Number are unique: no two Certificate Of Analysis records may share the same value, and a save that would duplicate one is rejected. Certificate Number and Status must be filled in before the record can be saved.

Quality Measurement refers back to Certificate Of Analysis, so what you change here can affect that record.

Every save starts as a Draft. The business rules and workflows attached to Certificate Of Analysis then run together in a single transaction: if all of them succeed the record becomes Final; if any of them fails, nothing they changed is kept — the record stays Draft and the reason is written onto it so you can fix the cause and retry. A Certificate Of Analysis with no rules or workflows attached is marked Final immediately.', 'M', FALSE, TRUE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_table (sys_table_id, table_name, name, description, access_level, is_view, is_document, is_high_volume, is_changelog, sys_window_id, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('7b6b19a0-83da-59f3-90c2-ea8b2030adbd', 'bus_certificate_of_analysis', 'Certificate Of Analysis', 'Controlled certificate presenting quality evidence for governed material. CertificateOfAnalysis is a released representation of underlying evidence, not a substitute for QualityInspection or QualityMeasurement. Supplier quality, customer documentation, regulated release, shipments, receipts, compliance, audit, and integrations. Inspections and measurements supply evidence; Product and receipt/shipment provide material context. Draft → approved → issued → superseded/void under controlled document history. Changes to open source evidence invalidate draft/approved certificates for revalidation; issued certificates retain historical source references and are corrected by supersession.', 'A', FALSE, FALSE, FALSE, TRUE, 'e0ebc497-91da-5163-9c3b-f937c5a035f9', 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_tab (sys_tab_id, sys_window_id, sys_table_id, name, help, tab_level, seq_no, is_single_row, has_tree, is_info_tab, is_translation_tab, is_read_only, is_insert_record, is_advanced_tab, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('cc7a203a-b12c-5c6c-945a-f607e8beb930', 'e0ebc497-91da-5163-9c3b-f937c5a035f9', '7b6b19a0-83da-59f3-90c2-ea8b2030adbd', 'Certificate Of Analysis', 'Shows one Certificate Of Analysis at a time. Fields are grouped: General carries the identifying fields and Details carries the rest. 2 fields marked with a red asterisk (*) must have a value before Save will accept the record. Any field showing a ? beside its label has help of its own; click it for the rules that apply there.', 0, 10, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
